var B64='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function b64encode(bytes){
  var out='', i;
  for(i=0;i+2<bytes.length;i+=3){
    var n=(bytes[i]<<16)|(bytes[i+1]<<8)|bytes[i+2];
    out+=B64[(n>>18)&63]+B64[(n>>12)&63]+B64[(n>>6)&63]+B64[n&63];
  }
  var rem=bytes.length-i;
  if(rem===1){ var a=bytes[i]<<16; out+=B64[(a>>18)&63]+B64[(a>>12)&63]+'=='; }
  else if(rem===2){ var b=(bytes[i]<<16)|(bytes[i+1]<<8); out+=B64[(b>>18)&63]+B64[(b>>12)&63]+B64[(b>>6)&63]+'='; }
  return out;
}

function b64decode(str){
  var s=String(str).replace(/[\s\r\n]/g,'');
  s=s.replace(/-/g,'+').replace(/_/g,'/');
  var pad=0;
  while(s.length && s[s.length-1]==='='){ s=s.slice(0,-1); pad++; }
  if(/[^A-Za-z0-9+/]/.test(s)) throw new Error('Base64 含非法字符');
  var out=[], buf=0, bits=0;
  for(var i=0;i<s.length;i++){
    var v=B64.indexOf(s[i]);
    buf=(buf<<6)|v; bits+=6;
    if(bits>=8){ bits-=8; out.push((buf>>bits)&0xff); }
  }
  return out;
}

function bytesToHex(bytes, sep){
  var s=[];
  for(var i=0;i<bytes.length;i++){ var h=bytes[i].toString(16); s.push(h.length<2?'0'+h:h); }
  return s.join(sep==null?'':sep);
}
function hexToBytes(hex){
  var s=String(hex).replace(/[^0-9a-fA-F]/g,'');
  if(s.length%2) s='0'+s;
  var out=[];
  for(var i=0;i<s.length;i+=2) out.push(parseInt(s.substr(i,2),16));
  return out;
}

function pemEncode(label, bytes){
  var b=b64encode(bytes), lines=[];
  for(var i=0;i<b.length;i+=64) lines.push(b.slice(i,i+64));
  return '-----BEGIN '+label+'-----\n'+lines.join('\n')+'\n-----END '+label+'-----';
}

function pemDecode(text){
  var s=String(text||'');
  var re=/-----BEGIN ([A-Z0-9 ]+)-----([\s\S]*?)-----END \1-----/g, m, out=[];
  while((m=re.exec(s))!==null){ out.push({label:m[1].trim(), bytes:b64decode(m[2])}); }
  if(!out.length){
    var t=s.trim();
    if(/^[0-9a-fA-F\s:]+$/.test(t) && t.replace(/[^0-9a-fA-F]/g,'').length>=4)
      return [{label:'RAW HEX', bytes:hexToBytes(t)}];
    if(t.length && /^[A-Za-z0-9+/=\s_-]+$/.test(t))
      return [{label:'RAW BASE64', bytes:b64decode(t)}];
    throw new Error('未找到 PEM 块，也不是合法的 Base64 / HEX');
  }
  return out;
}

var TAGS={1:'BOOLEAN',2:'INTEGER',3:'BIT STRING',4:'OCTET STRING',5:'NULL',6:'OBJECT IDENTIFIER',
  10:'ENUMERATED',12:'UTF8String',16:'SEQUENCE',17:'SET',19:'PrintableString',20:'T61String',
  22:'IA5String',23:'UTCTime',24:'GeneralizedTime',26:'VisibleString',27:'GeneralString',30:'BMPString'};

function tagName(tag){
  var cls=(tag>>6)&3, num=tag&0x1f;
  if(cls===2) return '['+num+']';
  if(cls===1) return 'APPLICATION '+num;
  if(cls===3) return 'PRIVATE '+num;
  return TAGS[num] || ('UNIVERSAL '+num);
}

function oidToString(b){
  if(!b || !b.length) return '';
  var first=b[0], out;
  if(first>=80) out=[2, first-80]; else out=[Math.floor(first/40), first%40];
  var v=0;
  for(var i=1;i<b.length;i++){
    v=v*128+(b[i]&0x7f);
    if(!(b[i]&0x80)){ out.push(v); v=0; }
  }
  return out.join('.');
}

function oidEncode(s){
  var p=String(s).split('.').map(Number);
  if(p.length<2) throw new Error('OID 至少需要两段');
  var out=[p[0]*40+p[1]];
  for(var i=2;i<p.length;i++){
    var v=p[i], stack=[v%128];
    v=Math.floor(v/128);
    while(v>0){ stack.unshift((v%128)|0x80); v=Math.floor(v/128); }
    out=out.concat(stack);
  }
  return out;
}

