function oidName(o){ return OIDS[o] || o; }

function decodeInt(b){
  if(!b.length) return 0;
  if(b.length>6) return '0x'+bytesToHex(b);
  var neg=(b[0]&0x80)!==0, v=0;
  for(var i=0;i<b.length;i++) v=v*256+b[i];
  if(neg) v=v-Math.pow(2,8*b.length);
  return v;
}
function encodeInt(n){
  if(n===0) return [0];
  var neg=n<0, v=Math.abs(n), bytes=[];
  while(v>0){ bytes.unshift(v%256); v=Math.floor(v/256); }
  if(!neg){ if(bytes[0]&0x80) bytes.unshift(0); return bytes; }
  var inv=bytes.map(function(x){ return (~x)&0xff; });
  var i=inv.length-1;
  while(i>=0){ inv[i]=(inv[i]+1)&0xff; if(inv[i]!==0) break; i--; }
  if(!(inv[0]&0x80)) inv.unshift(0xff);
  return inv;
}

function decodeString(b){
  var s='';
  for(var i=0;i<b.length;i++){
    var c=b[i];
    if(c<0x80){ s+=String.fromCharCode(c); }
    else if(c>=0xc0 && c<0xe0 && i+1<b.length){ s+=String.fromCharCode(((c&0x1f)<<6)|(b[++i]&0x3f)); }
    else if(c>=0xe0 && i+2<b.length){ var a=(c&0x0f)<<12; a|=(b[++i]&0x3f)<<6; a|=(b[++i]&0x3f); s+=String.fromCharCode(a); }
    else s+=String.fromCharCode(c);
  }
  return s;
}
function encodeString(s){
  var out=[];
  for(var i=0;i<s.length;i++){
    var c=s.charCodeAt(i);
    if(c<0x80) out.push(c);
    else if(c<0x800){ out.push(0xc0|(c>>6), 0x80|(c&0x3f)); }
    else { out.push(0xe0|(c>>12), 0x80|((c>>6)&0x3f), 0x80|(c&0x3f)); }
  }
  return out;
}

function parseTime(tag, b){
  var s=decodeString(b).replace(/Z$/,'');
  var y, rest;
  if(tag===23){ var yy=parseInt(s.slice(0,2),10); y=yy<50?2000+yy:1900+yy; rest=s.slice(2); }
  else { y=parseInt(s.slice(0,4),10); rest=s.slice(4); }
  function n(i){ return parseInt(rest.substr(i,2),10)||0; }
  var iso=pad4(y)+'-'+pad2(n(0))+'-'+pad2(n(2))+'T'+pad2(n(4))+':'+pad2(n(6))+':'+pad2(n(8))+'Z';
  return iso;
}
function pad2(v){ return (v<10?'0':'')+v; }
function pad4(v){ var s=String(v); while(s.length<4) s='0'+s; return s; }

function decodePrimitive(tag, b){
  var num=tag&0x1f, cls=(tag>>6)&3;
  if(cls!==0) return '0x'+bytesToHex(b).slice(0,80);
  if(num===1) return b.length ? b[0]!==0 : false;
  if(num===2 || num===10) return decodeInt(b);
  if(num===5) return null;
  if(num===6) return oidName(oidToString(b));
  if(num===3) return {unusedBits:b[0]||0, hex:bytesToHex(b.slice(1)).slice(0,120)};
  if(num===4) return '0x'+bytesToHex(b).slice(0,120);
  if(num===23 || num===24) return parseTime(num, b);
  if([12,19,20,22,26,27,30].indexOf(num)>=0) return decodeString(b);
  return '0x'+bytesToHex(b).slice(0,80);
}

function derParse(bytes, off, depth){
  off=off||0; depth=depth||0;
  if(depth>40) throw new Error('ASN.1 嵌套超过 40 层，疑似结构损坏');
  if(off>=bytes.length) throw new Error('偏移 '+off+' 越界');
  var tag=bytes[off], p=off+1;
  if((tag&0x1f)===0x1f) throw new Error('暂不支持高位标签（long-form tag）');
  if(p>=bytes.length) throw new Error('缺少长度字节');
  var l=bytes[p++], len;
  if(l<0x80) len=l;
  else {
    var n=l&0x7f;
    if(n===0) throw new Error('DER 不允许不定长编码（indefinite length）');
    if(n>4) throw new Error('长度字段 '+n+' 字节过长');
    if(p+n>bytes.length) throw new Error('长度字段截断');
    len=0; for(var i=0;i<n;i++) len=len*256+bytes[p++];
  }
  var cs=p, ce=p+len;
  if(ce>bytes.length) throw new Error('内容越界：声明 '+len+' 字节，实际剩余 '+(bytes.length-cs));
  var node={tag:tag, tagName:tagName(tag), cls:['universal','application','context','private'][(tag>>6)&3],
            constructed:!!(tag&0x20), start:off, headerLen:cs-off, length:len, end:ce, depth:depth};
  if(node.constructed){
    node.children=[]; var q=cs;
    while(q<ce){ var ch=derParse(bytes,q,depth+1); node.children.push(ch); q=ch.end; }
  } else {
    node.bytes=bytes.slice(cs,ce);
    node.value=decodePrimitive(tag, node.bytes);
  }
  return node;
}

function encodeLength(n){
  if(n<0x80) return [n];
  var b=[], v=n;
  while(v>0){ b.unshift(v%256); v=Math.floor(v/256); }
  return [0x80|b.length].concat(b);
}

function derEncode(node){
  var content;
  if(node.children){
    content=[];
    for(var i=0;i<node.children.length;i++) content=content.concat(derEncode(node.children[i]));
  } else content=(node.bytes||[]).slice();
  return [node.tag].concat(encodeLength(content.length), content);
}

var B={
  seq:function(ch){ return {tag:0x30, children:ch}; },
  set:function(ch){ return {tag:0x31, children:ch}; },
  ctx:function(n, ch){ return {tag:0xa0|n, children:ch}; },
  int:function(v){ return {tag:0x02, bytes:encodeInt(v)}; },
  bigint:function(hex){ var b=hexToBytes(hex); if(b[0]&0x80) b=[0].concat(b); return {tag:0x02, bytes:b}; },
  oid:function(s){ return {tag:0x06, bytes:oidEncode(s)}; },
  utf8:function(s){ return {tag:0x0c, bytes:encodeString(s)}; },
  printable:function(s){ return {tag:0x13, bytes:encodeString(s)}; },
  nul:function(){ return {tag:0x05, bytes:[]}; },
  bool:function(v){ return {tag:0x01, bytes:[v?0xff:0x00]}; },
  octet:function(b){ return {tag:0x04, bytes:b}; },
  bits:function(b, unused){ return {tag:0x03, bytes:[unused||0].concat(b)}; },
  utc:function(s){ return {tag:0x17, bytes:encodeString(s)}; },
  rdn:function(oid, val){ return B.set([B.seq([B.oid(oid), B.printable(val)])]); }
};

function nameToString(node){
  if(!node || !node.children) return '';
  var parts=[];
  node.children.forEach(function(rdnSet){
    (rdnSet.children||[]).forEach(function(atv){
      var kids=atv.children||[];
      if(kids.length<2) return;
      var key=kids[0].value, val=kids[1].value;
      parts.push(key+'='+val);
    });
  });
  return parts.join(', ');
}

function rsaKeyBits(intNode){
  if(!intNode || !intNode.bytes) return 0;
  var b=intNode.bytes.slice();
  while(b.length && b[0]===0) b=b.slice(1);
  if(!b.length) return 0;
  var top=b[0], lead=0;
  while(lead<8 && !((top>>(7-lead))&1)) lead++;
  return b.length*8-lead;
}

function readSpki(spki){
  var out={algorithm:'', keyBits:0, curve:null, exponent:null};
  if(!spki || !spki.children || spki.children.length<2) return out;
  var alg=spki.children[0], bits=spki.children[1];
  if(alg.children && alg.children[0]) out.algorithm=alg.children[0].value;
  if(alg.children && alg.children[1] && alg.children[1].tag===0x06) out.curve=alg.children[1].value;
  if(bits.bytes && bits.bytes.length>1){
    if(String(out.algorithm).indexOf('rsa')>=0){
      try {
        var inner=derParse(bits.bytes.slice(1));
        out.keyBits=rsaKeyBits(inner.children[0]);
        out.exponent=inner.children[1] ? inner.children[1].value : null;
      } catch(e){ out.keyBits=0; }
    } else {
      out.keyBits=(bits.bytes.length-2)*4;
    }
  }
  return out;
}

function findExtensions(tbs){
  var out=[];
  (tbs.children||[]).forEach(function(c){
    if(c.cls==='context' && (c.tag&0x1f)===3 && c.children && c.children[0]){
      (c.children[0].children||[]).forEach(function(ext){
        var k=ext.children||[];
        if(!k.length) return;
        var critical = k.length>1 && k[1].tag===0x01 ? !!k[1].value : false;
        out.push({oid:k[0].value, critical:critical});
      });
    }
  });
  return out;
}

function parseCertificate(bytes){
  var root=derParse(bytes);
  if(!root.children || root.children.length<2) throw new Error('不是合法的 Certificate 结构');
  var tbs=root.children[0];
  var kids=tbs.children||[];
  var i=0, version=1;
  if(kids[0] && kids[0].cls==='context' && (kids[0].tag&0x1f)===0){
    version=(kids[0].children&&kids[0].children[0]?kids[0].children[0].value:0)+1; i=1;
  }
  var serialNode=kids[i];
  var sigAlgNode=kids[i+1];
  var issuer=kids[i+2], validity=kids[i+3], subject=kids[i+4], spki=kids[i+5];
  var nb=validity&&validity.children?validity.children[0].value:null;
  var na=validity&&validity.children?validity.children[1].value:null;
  var key=readSpki(spki);
  var issuerStr=nameToString(issuer), subjectStr=nameToString(subject);
  return {
    kind:'certificate', version:version,
    serial: serialNode ? (typeof serialNode.value==='number' ? String(serialNode.value) : String(serialNode.value)) : '',
    serialHex: serialNode && serialNode.bytes ? bytesToHex(serialNode.bytes,':') : '',
    signatureAlgorithm: sigAlgNode && sigAlgNode.children ? sigAlgNode.children[0].value : '',
    issuer: issuerStr, subject: subjectStr,
    notBefore: nb, notAfter: na,
    publicKeyAlgorithm: key.algorithm, keyBits: key.keyBits, curve: key.curve, exponent: key.exponent,
    selfSigned: !!issuerStr && issuerStr===subjectStr,
    extensions: findExtensions(tbs),
    totalBytes: bytes.length
  };
}

function parseCsr(bytes){
  var root=derParse(bytes);
  var info=root.children[0];
  var kids=info.children||[];
  var subject=kids[1], spki=kids[2];
  var key=readSpki(spki);
  return {kind:'csr', version:(kids[0]?kids[0].value:0)+1, subject:nameToString(subject),
          publicKeyAlgorithm:key.algorithm, keyBits:key.keyBits, curve:key.curve,
          signatureAlgorithm: root.children[1] && root.children[1].children ? root.children[1].children[0].value : '',
          totalBytes: bytes.length};
}

function parseKey(label, bytes){
  var root=derParse(bytes);
  var kids=root.children||[];
  if(label.indexOf('PUBLIC')>=0 && label.indexOf('RSA')<0){
    var k=readSpki(root);
    return {kind:'public-key', publicKeyAlgorithm:k.algorithm, keyBits:k.keyBits, curve:k.curve,
            exponent:k.exponent, totalBytes:bytes.length};
  }
  if(label.indexOf('RSA PUBLIC')>=0){
    return {kind:'public-key', publicKeyAlgorithm:'rsaEncryption', keyBits:rsaKeyBits(kids[0]),
            exponent:kids[1]?kids[1].value:null, totalBytes:bytes.length};
  }
  if(label.indexOf('RSA PRIVATE')>=0){
    return {kind:'private-key', publicKeyAlgorithm:'rsaEncryption', keyBits:rsaKeyBits(kids[1]),
            exponent:kids[2]?kids[2].value:null, encrypted:false, totalBytes:bytes.length};
  }
  if(label.indexOf('EC PRIVATE')>=0){
    var curve=null;
    kids.forEach(function(c){ if(c.cls==='context' && c.children && c.children[0] && c.children[0].tag===0x06) curve=c.children[0].value; });
    return {kind:'private-key', publicKeyAlgorithm:'id-ecPublicKey', curve:curve,
            keyBits: kids[1] && kids[1].bytes ? kids[1].bytes.length*8 : 0, encrypted:false, totalBytes:bytes.length};
  }
  if(label.indexOf('ENCRYPTED')>=0){
    return {kind:'private-key', publicKeyAlgorithm:'unknown', encrypted:true, keyBits:0, totalBytes:bytes.length};
  }
  var alg=kids[1] && kids[1].children ? kids[1].children[0].value : 'unknown';
  var bitsOut=0, crv=null;
  if(kids[1] && kids[1].children && kids[1].children[1] && kids[1].children[1].tag===0x06) crv=kids[1].children[1].value;
  if(String(alg).indexOf('rsa')>=0 && kids[2] && kids[2].bytes){
    try { var inner=derParse(kids[2].bytes); bitsOut=rsaKeyBits(inner.children[1]); } catch(e){}
  }
  return {kind:'private-key', publicKeyAlgorithm:alg, keyBits:bitsOut, curve:crv, encrypted:false, totalBytes:bytes.length};
}

function inspect(text, nowMs){
  var blocks=pemDecode(text);
  return blocks.map(function(blk){
    var info, err=null;
    try {
      if(blk.label.indexOf('CERTIFICATE REQUEST')>=0) info=parseCsr(blk.bytes);
      else if(blk.label==='CERTIFICATE' || blk.label==='TRUSTED CERTIFICATE') info=parseCertificate(blk.bytes);
      else if(blk.label.indexOf('KEY')>=0) info=parseKey(blk.label, blk.bytes);
      else info={kind:'raw', totalBytes:blk.bytes.length};
    } catch(e){ err=e.message; info={kind:'raw', totalBytes:blk.bytes.length}; }
    var tree=null, terr=null;
    try { tree=derParse(blk.bytes); } catch(e2){ terr=e2.message; }
    return {label:blk.label, info:info, tree:tree, error:err||terr,
            warnings:lint(info, nowMs), pem:pemEncode(blk.label, blk.bytes)};
  });
}

function daysBetween(a,b){ return Math.round((b-a)/86400000); }

function lint(info, nowMs){
  var w=[];
  if(!info) return w;
  var now = nowMs==null ? null : nowMs;
  var alg=String(info.signatureAlgorithm||'').toLowerCase();
  if(alg.indexOf('sha1')>=0 || alg.indexOf('md5')>=0)
    w.push({level:'error', msg:'签名算法 '+info.signatureAlgorithm+' 已被主流浏览器和 CA/B 论坛淘汰，请改用 SHA-256 及以上'});
  if(info.keyBits && String(info.publicKeyAlgorithm||'').indexOf('rsa')>=0){
    if(info.keyBits<2048) w.push({level:'error', msg:'RSA 密钥仅 '+info.keyBits+' 位，低于 2048 位最低要求'});
    else if(info.keyBits<3072) w.push({level:'info', msg:'RSA '+info.keyBits+' 位满足当前要求，长期证书建议 3072 位或改用 ECDSA P-256'});
  }
  if(info.exponent!=null && info.exponent!==65537 && String(info.publicKeyAlgorithm||'').indexOf('rsa')>=0)
    w.push({level:'warn', msg:'RSA 公钥指数为 '+info.exponent+'，非标准值 65537，部分实现会拒绝'});
  if(info.notBefore && info.notAfter){
    var nb=Date.parse(info.notBefore), na=Date.parse(info.notAfter);
    if(isFinite(nb) && isFinite(na)){
      var days=daysBetween(nb,na);
      if(days>398) w.push({level:'warn', msg:'有效期 '+days+' 天超过 398 天上限，公共 CA 已不再签发这么长的证书'});
      if(days<=0) w.push({level:'error', msg:'notAfter 早于或等于 notBefore，有效期非法'});
      if(now!=null){
        if(now<nb) w.push({level:'error', msg:'证书尚未生效（notBefore '+info.notBefore+'）'});
        else if(now>na) w.push({level:'error', msg:'证书已过期（notAfter '+info.notAfter+'）'});
        else {
          var left=daysBetween(now,na);
          if(left<30) w.push({level:'warn', msg:'距离过期仅剩 '+left+' 天，请尽快续期'});
        }
      }
    }
  }
  if(info.selfSigned) w.push({level:'info', msg:'issuer 与 subject 相同，这是一张自签名证书'});
  if(info.kind==='certificate' && info.version!==3)
    w.push({level:'warn', msg:'证书版本为 v'+info.version+'，现代证书应为 v3 才能携带扩展'});
  if(info.kind==='certificate' && (!info.extensions || !info.extensions.length))
    w.push({level:'warn', msg:'没有解析到任何 X.509 扩展，缺少 subjectAltName 的证书会被浏览器直接拒绝'});
