function treeLines(node, out, indent){
  out=out||[]; indent=indent||0;
  var head=new Array(indent+1).join('  ')+node.tagName+' ('+node.length+')';
  if(!node.constructed){
    var v=node.value;
    if(v && typeof v==='object' && v.hex!=null) v='BIT STRING unused='+v.unusedBits+' '+v.hex;
    head += '  ' + (v===null?'NULL':String(v)).slice(0,100);
  }
  out.push({indent:indent, text:head, offset:node.start});
  (node.children||[]).forEach(function(c){ treeLines(c, out, indent+1); });
  return out;
}

